  <script>
    // ===== Header scroll shadow =====
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    });

    // ===== Mobile menu =====
    const hamburgerBtn = document.getElementById('hamburger-btn');
    const mobileOverlay = document.getElementById('mobile-overlay');
    const mobileDrawer = document.getElementById('mobile-drawer');
    const drawerClose = document.getElementById('drawer-close');

    function openMenu() {
      mobileOverlay.style.display = 'block';
      requestAnimationFrame(() => {
        mobileOverlay.classList.add('active');
        mobileDrawer.classList.add('active');
      });
      document.body.style.overflow = 'hidden';
    }

    function closeMenu() {
      mobileOverlay.classList.remove('active');
      mobileDrawer.classList.remove('active');
      setTimeout(() => { mobileOverlay.style.display = 'none'; }, 300);
      document.body.style.overflow = '';
    }

    hamburgerBtn.addEventListener('click', openMenu);
    drawerClose.addEventListener('click', closeMenu);
    mobileOverlay.addEventListener('click', closeMenu);

    mobileDrawer.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', closeMenu);
    });

    // ===== Search autocomplete =====
    const searchInput = document.getElementById('search-input');
    const dropdown = document.getElementById('autocomplete-dropdown');

    const suggestions = [
      { label: 'Dentist', category: 'Specialty' },
      { label: 'Dermatologist', category: 'Specialty' },
      { label: 'Primary Care Doctor', category: 'Specialty' },
      { label: 'Psychiatrist', category: 'Specialty' },
      { label: 'Eye Doctor', category: 'Specialty' },
      { label: 'Orthopedic Surgeon', category: 'Specialty' },
      { label: 'Back Pain', category: 'Condition' },
      { label: 'Anxiety', category: 'Condition' },
      { label: 'Skin Rash', category: 'Condition' },
      { label: 'Headache', category: 'Condition' },
      { label: 'Allergies', category: 'Condition' },
      { label: 'Dr. Sarah Chen', category: 'Doctor' },
      { label: 'Dr. Michael Rivera', category: 'Doctor' },
      { label: 'Dr. Emily Nakamura', category: 'Doctor' },
    ];

    function renderSuggestions(matches) {
      if (matches.length === 0) {
        dropdown.classList.remove('active');
        return;
      }
      dropdown.innerHTML = matches.map(s => {
        const iconSvg = s.category === 'Doctor'
          ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>'
          : s.category === 'Condition'
          ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v8"/><path d="M8 6h8"/><path d="M12 10c0 0-5 4-5 8a5 5 0 0 0 10 0c0-4-5-8-5-8z"/></svg>'
          : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>';
        return `<div class="autocomplete-item" data-value="${s.label}">${iconSvg}<span class="label">${s.label}</span><span class="category">${s.category}</span></div>`;
      }).join('');
      dropdown.classList.add('active');

      dropdown.querySelectorAll('.autocomplete-item').forEach(item => {
        item.addEventListener('mousedown', (e) => {
          e.preventDefault();
          searchInput.value = item.dataset.value;
          dropdown.classList.remove('active');
        });
      });
    }

    searchInput.addEventListener('input', () => {
      const val = searchInput.value.trim().toLowerCase();
      if (val.length < 2) {
        dropdown.classList.remove('active');
        return;
      }
      const matches = suggestions.filter(s => s.label.toLowerCase().includes(val));
      renderSuggestions(matches);
    });

    searchInput.addEventListener('focus', () => {
      if (searchInput.value.trim().length >= 2) {
        const val = searchInput.value.trim().toLowerCase();
        const matches = suggestions.filter(s => s.label.toLowerCase().includes(val));
        renderSuggestions(matches);
      }
    });

    searchInput.addEventListener('blur', () => {
      setTimeout(() => dropdown.classList.remove('active'), 150);
    });

    // ===== Search form submit =====
    document.getElementById('search-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const q = searchInput.value.trim();
      const loc = document.getElementById('location-input').value.trim();
      const ins = document.getElementById('insurance-select').value;
      const params = new URLSearchParams();
      if (q) params.set('q', q);
      if (loc) params.set('loc', loc);
      if (ins) params.set('ins', ins);
      // Navigate to search results
      window.location.href = 'index.html?search=' + encodeURIComponent(params.toString());
    });

    // ===== Specialty card click =====
    document.querySelectorAll('.specialty-card').forEach(card => {
      card.addEventListener('click', (e) => {
        e.preventDefault();
        const specialty = card.dataset.specialty;
        searchInput.value = specialty;
        searchInput.focus();
        // Scroll to search
        document.querySelector('.search-section').scrollIntoView({ behavior: 'smooth' });
      });
    });

    // ===== Scroll animations =====
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.fade-up').forEach(el => observer.observe(el));
  </script>
